Particle [] p = new Array(250);

function setup(){
  createCanvas(800, 800);
  background(0);
	colorMode(HSB,360,100,100);
  noStroke();
  for(i = 0; i < 250; i++){
    p[i] = new Particle();
  }
}

function draw(){
  fill(0,6);
  rect(0,0,width,height);
  for(i = 0; i < 250; i++){
    p[i].display();
    p[i].check();
    p[i].move();
  }
}

