class Particle{

  x, y, ra;
  d,r,g,b,col,s,b;
  c;

  let v = new PVector();

  constructor(){
		col=0;
		s=int(random(80,100));
		b=int(random(80,100));
    ra = random(2,20);
    x = random(ra,width-ra);
    y = random(ra,height-ra);
    d = int(random(10,300));
    let alpha = random(0,TWO_PI);
    v.x = cos(alpha);
    v.y = sin(alpha);
    /*let z = random(0,1);
    if(z<0.25){
      r=0; g = 0; b = 255;
    }
    else
    if(z < 0.5){
    r = 0; g = 255; b = 0;}
    else
    if(z < 0.75)
    {r = 255; g = 0; b = 0;}
    else 
    {r=255;g=255;b=0;}
		*/
  }

  function display(){
		changeColor();
    fill(c);
    ellipse(x,y,2*ra,2*ra);
  }

  function changeColor(){
		col = frameCount%360;
	  c = color(col,s,b);
	}

  function move(){
    if(d > 0){
      x += v.x;
      y += v.y;
      d--;
    }
    else{
      var alpha = random(0,TWO_PI);
       v.x = cos(alpha);
       v.y = sin(alpha);
       d = int(random(10,300));
    }   
  } 


  function check(){
  if ((x <= ra) || (x >= (width-ra))){
    v.x *= -1;
  }
  if ((y <= ra) || (y >= (height -ra))){
    v.y *= -1;
  }

  }

}

